-- Упражнения книги 19, глава 25 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-describe-domain', 0, 'func', 'Разбор info() и state()', 'Метод info() домена возвращает список [state, maxMem, memory, nrVirtCpu, cpuTime]: maxMem и memory в КиБ, cpuTime в наносекундах. Метод state() возвращает пару [state, reason]. Напишите функцию describe_domain(info, reason): info — список из info(), reason — вторая часть пары из state(). Верните кортеж из шести значений: имя состояния, имя причины, максимум памяти в МиБ (целочисленное деление на 1024), память в МиБ (так же), число vCPU и CPU-время в секундах, округлённое до двух знаков. Имена состояний по номерам 0..7: nostate, running, blocked, paused, shutdown, shutoff, crashed, pmsuspended; номер вне этого диапазона даёт unknown. Имена причин зависят от состояния: running: 1 booted, 2 migrated, 3 restored, 4 from_snapshot, 5 unpaused; paused: 1 user, 2 migration, 3 save, 4 dump, 5 ioerror, 6 watchdog, 7 from_snapshot; shutoff: 1 shutdown, 2 destroyed, 3 crashed, 4 migrated, 5 saved, 6 failed, 7 from_snapshot; crashed: 1 panicked. Любая другая комбинация, включая причину 0, даёт unknown.', 'def describe_domain(info, reason):
    pass
', 'Две таблицы: список имён состояний и словарь словарей причин; reasons.get(state, {}).get(reason, ''unknown'').', '{"func": "describe_domain", "tests": [{"args": [[1, 4194304, 4194304, 4, 123456789012], 1], "expected": {"__tuple__": ["running", "booted", 4096, 4096, 4, 123.46]}}, {"args": [[3, 2097152, 2097152, 2, 5000000000], 1], "expected": {"__tuple__": ["paused", "user", 2048, 2048, 2, 5.0]}}, {"args": [[5, 2097152, 0, 2, 0], 2], "expected": {"__tuple__": ["shutoff", "destroyed", 2048, 0, 2, 0.0]}}, {"args": [[5, 1048576, 0, 1, 987654321], 0], "expected": {"__tuple__": ["shutoff", "unknown", 1024, 0, 1, 0.99]}}, {"args": [[6, 1048576, 524288, 1, 1500000000], 1], "expected": {"__tuple__": ["crashed", "panicked", 1024, 512, 1, 1.5]}}, {"args": [[1, 1048576, 1048576, 1, 42], 0], "expected": {"__tuple__": ["running", "unknown", 1024, 1024, 1, 0.0]}}, {"args": [[4, 1572864, 1572864, 3, 7777777777], 1], "expected": {"__tuple__": ["shutdown", "unknown", 1536, 1536, 3, 7.78]}}, {"args": [[9, 1024, 1024, 1, 0], 1], "expected": {"__tuple__": ["unknown", "unknown", 1, 1, 1, 0.0]}}, {"args": [[3, 1024000, 1024000, 8, 999999999999], 5], "expected": {"__tuple__": ["paused", "ioerror", 1000, 1000, 8, 1000.0]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-cpu-percent', 1, 'func', 'Процент CPU по двум замерам', 'Домен опрашивают периодически и получают замеры (секунды, cpuTime): время по часам хоста в секундах и накопительный счётчик cpuTime в наносекундах. Напишите функцию cpu_percent(samples, vcpus): для каждой пары соседних замеров верните процент занятости от ёмкости гостя, то есть прирост cpuTime, делённый на (прошедшие секунды × 1e9 × vcpus) и умноженный на 100, округлённый до одного знака. Значение не ограничивайте сверху: время гипервизора тоже входит в счётчик. Если время между замерами не растёт (разность 0 или меньше) или счётчик уменьшился (домен перезапущен), для этой пары в ответ идёт None. Ответ — список длиной на единицу меньше числа замеров, для менее чем двух замеров — пустой список.', 'def cpu_percent(samples, vcpus):
    pass
', 'zip(samples, samples[1:]) даёт пары; проверьте dt <= 0 и dc < 0 до деления.', '{"func": "cpu_percent", "tests": [{"args": [[{"__tuple__": [0, 1000000000]}, {"__tuple__": [5, 6000000000]}], 2], "expected": [50.0]}, {"args": [[{"__tuple__": [0, 0]}, {"__tuple__": [10, 2500000000]}, {"__tuple__": [20, 12500000000]}], 1], "expected": [25.0, 100.0]}, {"args": [[{"__tuple__": [100.0, 5000000000]}, {"__tuple__": [130.0, 5000000000]}], 4], "expected": [0.0]}, {"args": [[{"__tuple__": [0, 900000000000]}, {"__tuple__": [5, 4000000]}], 2], "expected": [null]}, {"args": [[{"__tuple__": [0, 0]}, {"__tuple__": [5, 5000000000]}, {"__tuple__": [5, 6000000000]}, {"__tuple__": [6, 7500000000]}], 1], "expected": [100.0, null, 150.0]}, {"args": [[{"__tuple__": [0, 0]}], 2], "expected": []}, {"args": [[], 2], "expected": []}, {"args": [[{"__tuple__": [0, 0]}, {"__tuple__": [60, 90000000000]}], 4], "expected": [37.5]}, {"args": [[{"__tuple__": [0, 0]}, {"__tuple__": [2, 5000000000]}], 2], "expected": [125.0]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-summarize-stats', 2, 'func', 'Плоские ключи getAllDomainStats', 'conn.getAllDomainStats() возвращает список пар (домен, словарь) с плоскими ключами. Здесь вместо объекта домена в паре стоит его имя. Напишите функцию summarize_stats(records): верните словарь имя → словарь с пятью ключами. state — имя состояния по числу state.state (номера 0..7: nostate, running, blocked, paused, shutdown, shutoff, crashed, pmsuspended; ключа нет или номер вне диапазона — unknown). vcpus — vcpu.current (нет ключа — 0). mem_mib — balloon.current в КиБ, делённый нацело на 1024 (нет ключа — 0). disks — список кортежей (имя, прочитано байт, записано байт) для индексов от 0 до block.count − 1 по ключам block.N.name, block.N.rd.bytes, block.N.wr.bytes; отсутствующее имя — пустая строка, отсутствующее число — 0; нет block.count — пустой список. nets — то же для сетевых интерфейсов: кортежи (имя, rx, tx) по ключам net.count, net.N.name, net.N.rx.bytes, net.N.tx.bytes.', 'def summarize_stats(records):
    pass
', 'Ключ собирайте как ''block.%d.'' % i + суффикс и читайте через s.get(ключ, умолчание).', '{"func": "summarize_stats", "tests": [{"args": [[]], "expected": {}}, {"args": [[{"__tuple__": ["web", {"state.state": 1, "state.reason": 1, "cpu.time": 91000000000, "balloon.current": 4194304, "balloon.maximum": 4194304, "vcpu.current": 4, "vcpu.maximum": 4, "block.count": 2, "block.0.name": "vda", "block.0.rd.bytes": 1048576, "block.0.wr.bytes": 524288, "block.1.name": "vdb", "block.1.rd.bytes": 0, "block.1.wr.bytes": 4096, "net.count": 1, "net.0.name": "vnet0", "net.0.rx.bytes": 123456, "net.0.tx.bytes": 654321}]}]], "expected": {"web": {"state": "running", "vcpus": 4, "mem_mib": 4096, "disks": [{"__tuple__": ["vda", 1048576, 524288]}, {"__tuple__": ["vdb", 0, 4096]}], "nets": [{"__tuple__": ["vnet0", 123456, 654321]}]}}}, {"args": [[{"__tuple__": ["web", {"state.state": 1, "state.reason": 1, "cpu.time": 91000000000, "balloon.current": 4194304, "balloon.maximum": 4194304, "vcpu.current": 4, "vcpu.maximum": 4, "block.count": 2, "block.0.name": "vda", "block.0.rd.bytes": 1048576, "block.0.wr.bytes": 524288, "block.1.name": "vdb", "block.1.rd.bytes": 0, "block.1.wr.bytes": 4096, "net.count": 1, "net.0.name": "vnet0", "net.0.rx.bytes": 123456, "net.0.tx.bytes": 654321}]}, {"__tuple__": ["backup", {"state.state": 5, "state.reason": 1, "balloon.maximum": 2097152}]}]], "expected": {"web": {"state": "running", "vcpus": 4, "mem_mib": 4096, "disks": [{"__tuple__": ["vda", 1048576, 524288]}, {"__tuple__": ["vdb", 0, 4096]}], "nets": [{"__tuple__": ["vnet0", 123456, 654321]}]}, "backup": {"state": "shutoff", "vcpus": 0, "mem_mib": 0, "disks": [], "nets": []}}}, {"args": [[{"__tuple__": ["odd", {"state.state": 3, "vcpu.current": 1, "balloon.current": 1536, "block.count": 1, "block.0.name": "sda", "block.0.wr.bytes": 77, "net.count": 2, "net.0.name": "vnet1", "net.0.rx.bytes": 5, "net.0.tx.bytes": 6, "net.1.name": "vnet2", "net.1.rx.bytes": 9}]}]], "expected": {"odd": {"state": "paused", "vcpus": 1, "mem_mib": 1, "disks": [{"__tuple__": ["sda", 0, 77]}], "nets": [{"__tuple__": ["vnet1", 5, 6]}, {"__tuple__": ["vnet2", 9, 0]}]}}}, {"args": [[{"__tuple__": ["x", {"state.state": 42}]}]], "expected": {"x": {"state": "unknown", "vcpus": 0, "mem_mib": 0, "disks": [], "nets": []}}}, {"args": [[{"__tuple__": ["gone", {}]}]], "expected": {"gone": {"state": "unknown", "vcpus": 0, "mem_mib": 0, "disks": [], "nets": []}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-stop-calls', 3, 'func', 'Мягкая остановка с дедлайном', 'Скрипт останавливает домен так: если домен уже выключен (состояние 5, shutoff), ничего не делает. Иначе вызывает shutdown, затем опрашивает state() через каждые interval секунд: в моменты interval, 2·interval, 3·interval и так далее, пока момент не превысит timeout. Если очередной опрос показал состояние 5, скрипт заканчивает. Если время вышло, а домен не выключился, вызывает destroy. Напишите функцию stop_calls(initial_state, timeout, interval, states): states — состояния, которые покажут последовательные опросы (k-й опрос видит states[k], после конца списка повторяется последнее значение; пустой список означает состояние 1 всегда). Верните список вызовов в порядке выполнения: строки shutdown, затем state@T для каждого опроса (T — момент в секундах), в конце destroy, если домен так и не выключился. Выключенный с самого начала домен даёт пустой список.', 'def stop_calls(initial_state, timeout, interval, states):
    pass
', 'Цикл while t <= timeout; состояние опроса k — states[min(k, len(states) - 1)]; destroy после цикла.', '{"func": "stop_calls", "tests": [{"args": [5, 30, 5, [1]], "expected": []}, {"args": [1, 30, 5, [4, 4, 5]], "expected": ["shutdown", "state@5", "state@10", "state@15"]}, {"args": [1, 20, 5, [1, 1, 1, 1]], "expected": ["shutdown", "state@5", "state@10", "state@15", "state@20", "destroy"]}, {"args": [1, 20, 5, [1, 1, 1, 5]], "expected": ["shutdown", "state@5", "state@10", "state@15", "state@20"]}, {"args": [1, 20, 5, [1, 1, 1, 1, 5]], "expected": ["shutdown", "state@5", "state@10", "state@15", "state@20", "destroy"]}, {"args": [3, 12, 5, [3]], "expected": ["shutdown", "state@5", "state@10", "destroy"]}, {"args": [1, 4, 5, [5]], "expected": ["shutdown", "destroy"]}, {"args": [1, 10, 10, []], "expected": ["shutdown", "state@10", "destroy"]}, {"args": [1, 15, 10, [4, 5]], "expected": ["shutdown", "state@10", "destroy"]}, {"args": [6, 6, 2, [6, 5]], "expected": ["shutdown", "state@2", "state@4"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-track-events', 4, 'func', 'События в таблицу состояний', 'Монитор хранит таблицу «домен → последнее известное состояние» по событиям жизненного цикла (conn, dom, event, detail). Напишите функцию track_events(initial, events): initial — словарь имя → кортеж (состояние, постоянный ли домен), events — список кортежей (имя, event, detail). Верните итоговый словарь имя → состояние (строка). Правила этой модели. event 0 (defined): неизвестный домен появляется как (shutoff, постоянный), известный становится постоянным, состояние не меняется. event 1 (undefined): домен перестаёт быть постоянным; если его состояние shutoff, запись удаляется, иначе остаётся (домен живёт как временный). event 2 (started) и 4 (resumed): состояние running. event 3 (suspended): paused, а при detail 2 — paused:ioerror, при detail 3 — paused:watchdog. event 5 (stopped): постоянный домен получает shutoff, временный удаляется из таблицы; неизвестный домен игнорируется. event 6 (shutdown): shutting-down. event 7 (pmsuspended): pmsuspended. event 8 (crashed): crashed. Для событий 2, 3, 4, 6, 7, 8 неизвестный домен добавляется как временный. Любой другой номер события игнорируется.', 'def track_events(initial, events):
    pass
', 'Храните [состояние, постоянный] списком в словаре и меняйте его по номеру события; в конце оставьте только состояния.', '{"func": "track_events", "tests": [{"args": [{}, []], "expected": {}}, {"args": [{"web": {"__tuple__": ["shutoff", true]}}, [{"__tuple__": ["web", 2, 0]}, {"__tuple__": ["web", 3, 0]}, {"__tuple__": ["web", 4, 0]}]], "expected": {"web": "running"}}, {"args": [{"web": {"__tuple__": ["running", true]}}, [{"__tuple__": ["web", 6, 1]}, {"__tuple__": ["web", 5, 0]}]], "expected": {"web": "shutoff"}}, {"args": [{}, [{"__tuple__": ["tmp", 2, 0]}, {"__tuple__": ["tmp", 5, 0]}]], "expected": {}}, {"args": [{"db": {"__tuple__": ["running", true]}}, [{"__tuple__": ["db", 1, 0]}, {"__tuple__": ["db", 5, 0]}]], "expected": {}}, {"args": [{"db": {"__tuple__": ["running", true]}}, [{"__tuple__": ["db", 1, 0]}, {"__tuple__": ["db", 0, 0]}, {"__tuple__": ["db", 5, 0]}]], "expected": {"db": "shutoff"}}, {"args": [{}, [{"__tuple__": ["new", 0, 0]}, {"__tuple__": ["new", 2, 0]}, {"__tuple__": ["new", 3, 2]}, {"__tuple__": ["old", 3, 3]}, {"__tuple__": ["new", 4, 0]}]], "expected": {"new": "running", "old": "paused:watchdog"}}, {"args": [{"a": {"__tuple__": ["shutoff", true]}}, [{"__tuple__": ["a", 1, 0]}, {"__tuple__": ["b", 8, 0]}, {"__tuple__": ["c", 7, 0]}, {"__tuple__": ["a", 9, 0]}, {"__tuple__": ["zzz", 5, 0]}]], "expected": {"b": "crashed", "c": "pmsuspended"}}, {"args": [{"w": {"__tuple__": ["running", true]}}, [{"__tuple__": ["w", 3, 0]}, {"__tuple__": ["w", 3, 7]}, {"__tuple__": ["w", 8, 0]}, {"__tuple__": ["w", 5, 2]}]], "expected": {"w": "shutoff"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-plan-attempts', 5, 'func', 'Таблица ошибок и повторы', 'Операция над доменом (op — start, stop или snapshot-delete) выполняется несколькими попытками. codes — результаты попыток по порядку: None для успеха или get_error_code() ошибки. Напишите функцию plan_attempts(op, codes, max_retries): верните журнал действий. Таблица действий: None — ok; коды 5, 6, 39 (нет соединения, неверное соединение, ошибка RPC) — reconnect; коды 9 и 68 (операция не удалась, тайм-аут) — retry; код 55 (операция неприменима к состоянию) — ok для start и stop, fail для остальных операций; код 42 (нет домена) — ok для stop, иначе fail; код 72 (нет снимка) — ok для snapshot-delete, иначе fail; любой другой код — fail. Действия ok и fail заканчивают работу: после них попытки не разбираются. Действия retry и reconnect расходуют бюджет повторов max_retries: если бюджет уже исчерпан, вместо них в журнал идёт give-up, и работа заканчивается. Если попытки кончились раньше, журнал возвращается как есть. Журнал — список строк действий в порядке попыток.', 'def plan_attempts(op, codes, max_retries):
    pass
', 'Функция действия по (op, code), счётчик used; перед retry/reconnect проверьте used >= max_retries.', '{"func": "plan_attempts", "tests": [{"args": ["start", [null], 3], "expected": ["ok"]}, {"args": ["start", [55], 3], "expected": ["ok"]}, {"args": ["stop", [42], 3], "expected": ["ok"]}, {"args": ["start", [42], 3], "expected": ["fail"]}, {"args": ["snapshot-delete", [72], 3], "expected": ["ok"]}, {"args": ["snapshot-delete", [55], 3], "expected": ["fail"]}, {"args": ["start", [5, 6, null], 3], "expected": ["reconnect", "reconnect", "ok"]}, {"args": ["start", [9, 68, 9, 9], 2], "expected": ["retry", "retry", "give-up"]}, {"args": ["stop", [68, 39, 55], 5], "expected": ["retry", "reconnect", "ok"]}, {"args": ["start", [88], 3], "expected": ["fail"]}, {"args": ["start", [9], 0], "expected": ["give-up"]}, {"args": ["start", [], 3], "expected": []}, {"args": ["stop", [9, 9], 5], "expected": ["retry", "retry"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-snapshot-outline', 6, 'func', 'Дерево снимков', 'Для каждого снимка домена известны имя и имя родителя (getParent() корня вызывает ошибку, такой снимок записан с родителем None). Напишите функцию snapshot_outline(snaps, current): snaps — список кортежей (имя, родитель или None) в произвольном порядке, current — имя текущего снимка или любая строка, которой среди снимков нет. Верните список строк дерева в порядке обхода в глубину: корни по алфавиту, под каждым его дети по алфавиту. Строка — по два пробела отступа на уровень глубины и имя; у текущего снимка к имени добавляется пробел и звёздочка. Снимок, чей родитель отсутствует в списке, считается корнем.', 'def snapshot_outline(snaps, current):
    pass
', 'Постройте словарь родитель → дети, затем рекурсивная функция walk(name, depth) с sorted(children).', '{"func": "snapshot_outline", "tests": [{"args": [[], ""], "expected": []}, {"args": [[{"__tuple__": ["base", null]}], "base"], "expected": ["base *"]}, {"args": [[{"__tuple__": ["base", null]}, {"__tuple__": ["patched", "base"]}, {"__tuple__": ["tested", "patched"]}], "tested"], "expected": ["base", "  patched", "    tested *"]}, {"args": [[{"__tuple__": ["tested", "patched"]}, {"__tuple__": ["patched", "base"]}, {"__tuple__": ["base", null]}, {"__tuple__": ["experiment", "base"]}], ""], "expected": ["base", "  experiment", "  patched", "    tested"]}, {"args": [[{"__tuple__": ["b", "a"]}, {"__tuple__": ["c", "a"]}, {"__tuple__": ["d", "b"]}, {"__tuple__": ["a", null]}, {"__tuple__": ["e", "d"]}], "c"], "expected": ["a", "  b", "    d", "      e", "  c *"]}, {"args": [[{"__tuple__": ["x", null]}, {"__tuple__": ["a", null]}, {"__tuple__": ["a2", "a"]}], "none"], "expected": ["a", "  a2", "x"]}, {"args": [[{"__tuple__": ["child", "gone"]}, {"__tuple__": ["root", null]}], "child"], "expected": ["child *", "root"]}, {"args": [[{"__tuple__": ["s2", "s1"]}, {"__tuple__": ["s10", "s1"]}, {"__tuple__": ["s1", null]}], "s1"], "expected": ["s1 *", "  s10", "  s2"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-memory-report', 7, 'func', 'Отчёт по memoryStats', 'dom.memoryStats() возвращает словарь, все размеры в КиБ; какие-то ключи могут отсутствовать (нужны драйвер баллона в госте и включённая статистика). Ключи: actual — текущий размер баллона, available — вся память, видимая гостю, unused — память, не занятая ничем (кэш сюда не входит как свободный), usable — сколько можно отдать, не загнав гостя в своп (для Linux это MemAvailable), rss — резидентная память процесса QEMU на хосте. Напишите функцию memory_report(stats, max_kib): max_kib — максимум памяти домена из info(). Верните словарь из четырёх ключей. used_pct — (available − unused) / available × 100, округлено до одного знака, а если available отсутствует или равно 0, либо unused нет — None. real_used_pct — то же, но с usable вместо unused (None при отсутствии ключей или нулевом available). ballooned_mib — (max_kib − actual) // 1024, где отсутствующий actual считается равным max_kib. rss_mib — rss // 1024 или None, если ключа нет.', 'def memory_report(stats, max_kib):
    pass
', 'stats.get(...) для каждого ключа; if avail and unused is not None — защита и от нуля, и от отсутствия.', '{"func": "memory_report", "tests": [{"args": [{"actual": 4194304, "available": 4001000, "unused": 400100, "usable": 2000500, "rss": 4300000, "swap_in": 0}, 4194304], "expected": {"used_pct": 90.0, "real_used_pct": 50.0, "ballooned_mib": 0, "rss_mib": 4199}}, {"args": [{"actual": 2097152, "available": 2000000, "unused": 1000000, "rss": 2200000}, 4194304], "expected": {"used_pct": 50.0, "real_used_pct": null, "ballooned_mib": 2048, "rss_mib": 2148}}, {"args": [{"actual": 1048576, "rss": 1100000}, 1048576], "expected": {"used_pct": null, "real_used_pct": null, "ballooned_mib": 0, "rss_mib": 1074}}, {"args": [{}, 2097152], "expected": {"used_pct": null, "real_used_pct": null, "ballooned_mib": 0, "rss_mib": null}}, {"args": [{"available": 0, "unused": 0, "usable": 0, "actual": 524288}, 524288], "expected": {"used_pct": null, "real_used_pct": null, "ballooned_mib": 0, "rss_mib": null}}, {"args": [{"actual": 3145728, "available": 3000000, "unused": 3000000, "usable": 3000000, "rss": 1024}, 4194304], "expected": {"used_pct": 0.0, "real_used_pct": 0.0, "ballooned_mib": 1024, "rss_mib": 1}}, {"args": [{"available": 1000, "usable": 250, "last_update": 1700000000}, 2048], "expected": {"used_pct": null, "real_used_pct": 75.0, "ballooned_mib": 0, "rss_mib": null}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-counter-rates', 8, 'func', 'Скорость по счётчикам', 'blockStats() и interfaceStats() отдают накопительные счётчики; поле со значением −1 означает, что гипервизор эту статистику не поддерживает. После перезапуска домена счётчики начинаются с нуля. Напишите функцию counter_rates(samples): samples — список замеров (секунды, значение). Для каждой пары соседних замеров верните скорость в единицах в секунду, округлённую до одного знака. Если счётчик уменьшился (домен перезапускался), считайте, что он обнулился между замерами и вырос до нового значения: прирост равен новому значению. Если время не растёт (разность 0 или меньше) или любое из двух значений равно −1, для пары в ответ идёт None. Для менее чем двух замеров ответ — пустой список.', 'def counter_rates(samples):
    pass
', 'Порядок проверок: сначала dt и −1, потом сравнение v1 >= v0 для обычного прироста или сброса.', '{"func": "counter_rates", "tests": [{"args": [[{"__tuple__": [0, 1000]}, {"__tuple__": [10, 6000]}, {"__tuple__": [20, 6000]}]], "expected": [500.0, 0.0]}, {"args": [[{"__tuple__": [0, 5000]}, {"__tuple__": [5, 100]}, {"__tuple__": [10, 600]}]], "expected": [20.0, 100.0]}, {"args": [[{"__tuple__": [0, -1]}, {"__tuple__": [5, -1]}, {"__tuple__": [10, -1]}]], "expected": [null, null]}, {"args": [[{"__tuple__": [0, 0]}, {"__tuple__": [4, 1000]}, {"__tuple__": [4, 2000]}, {"__tuple__": [6, 3000]}]], "expected": [250.0, null, 500.0]}, {"args": [[{"__tuple__": [0, 10]}]], "expected": []}, {"args": [[]], "expected": []}, {"args": [[{"__tuple__": [0, 100]}, {"__tuple__": [3, 101]}, {"__tuple__": [6, -1]}, {"__tuple__": [9, 400]}]], "expected": [0.3, null, null]}, {"args": [[{"__tuple__": [0, 900000]}, {"__tuple__": [30, 0]}, {"__tuple__": [60, 1800000]}]], "expected": [0.0, 60000.0]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 25, 'la25-domain-plan', 9, 'func', 'План по XML домена', 'XML домена из XMLDesc() читают модулем xml.etree.ElementTree. Напишите функцию domain_plan(xml): xml — строка с корнем domain. Верните словарь из семи ключей. name — текст элемента name. memory_kib — значение memory в КиБ: у элемента есть необязательный атрибут unit, по умолчанию KiB; допустимы b и bytes (1), KB (1000), k и KiB (1024), MB (10^6), M и MiB (1024^2), GB (10^9), G и GiB (1024^3), TB (10^12), T и TiB (1024^4) байт; результат делится на 1024 с округлением вверх до целого. current_kib — то же для currentMemory, а если элемента нет, значение равно memory_kib. vcpus — число в элементе vcpu. current_vcpus — значение его атрибута current, а если атрибута нет, то vcpus. disks — отсортированный список значений dev элементов target внутри каждого devices/disk (cdrom тоже входит). next_disk — первое свободное имя virtio-диска: имена vda, vdb, …, vdz, vdaa, vdab, … (после z идёт aa, ab, …, az, ba, …), которого нет в disks.', 'def domain_plan(xml):
    pass
', 'root.find(''vcpu'').get(''current''); округление вверх: -(-nbytes // 1024); имена перебирайте циклом по индексу i → буквы.', '{"func": "domain_plan", "tests": [{"args": ["<domain type=''kvm''>\n  <name>web01</name>\n  <uuid>6f1c2d3e-0000-4000-8000-0123456789ab</uuid>\n  <memory unit=''KiB''>2097152</memory>\n  <currentMemory unit=''KiB''>1048576</currentMemory>\n  <vcpu placement=''static''>4</vcpu>\n  <os><type arch=''x86_64'' machine=''pc-q35-8.2''>hvm</type></os>\n  <devices>\n    <disk type=''file'' device=''disk''>\n      <driver name=''qemu'' type=''qcow2''/>\n      <source file=''/var/lib/libvirt/images/web01.qcow2''/>\n      <target dev=''vda'' bus=''virtio''/>\n    </disk>\n    <disk type=''file'' device=''cdrom''>\n      <source file=''/srv/iso/seed.iso''/>\n      <target dev=''sda'' bus=''sata''/>\n      <readonly/>\n    </disk>\n    <interface type=''network''><source network=''default''/><model type=''virtio''/></interface>\n  </devices>\n</domain>\n"], "expected": {"name": "web01", "memory_kib": 2097152, "current_kib": 1048576, "vcpus": 4, "current_vcpus": 4, "disks": ["sda", "vda"], "next_disk": "vdb"}}, {"args": ["<domain type=''kvm''>\n  <name>db-main</name>\n  <memory unit=''GiB''>8</memory>\n  <vcpu current=''2''>8</vcpu>\n  <devices>\n    <disk type=''block'' device=''disk''><source dev=''/dev/vg0/db''/><target dev=''vda'' bus=''virtio''/></disk>\n    <disk type=''block'' device=''disk''><source dev=''/dev/vg0/db2''/><target dev=''vdb'' bus=''virtio''/></disk>\n    <disk type=''block'' device=''disk''><source dev=''/dev/vg0/db3''/><target dev=''vdd'' bus=''virtio''/></disk>\n  </devices>\n</domain>\n"], "expected": {"name": "db-main", "memory_kib": 8388608, "current_kib": 8388608, "vcpus": 8, "current_vcpus": 2, "disks": ["vda", "vdb", "vdd"], "next_disk": "vdc"}}, {"args": ["<domain type=''kvm''>\n  <name>tiny</name>\n  <memory unit=''MB''>1500</memory>\n  <currentMemory unit=''M''>1000</currentMemory>\n  <vcpu>1</vcpu>\n  <devices>\n    <emulator>/usr/bin/qemu-system-x86_64</emulator>\n  </devices>\n</domain>\n"], "expected": {"name": "tiny", "memory_kib": 1464844, "current_kib": 1024000, "vcpus": 1, "current_vcpus": 1, "disks": [], "next_disk": "vda"}}, {"args": ["<domain type=''kvm''><name>big</name><memory>1000001</memory><vcpu>2</vcpu><devices><disk device=''disk''><target dev=''vda'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdb'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdc'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdd'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vde'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdf'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdg'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdh'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdi'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdj'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdk'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdl'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdm'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdn'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdo'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdp'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdq'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdr'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vds'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdt'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdu'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdv'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdw'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdx'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdy'' bus=''virtio''/></disk><disk device=''disk''><target dev=''vdz'' bus=''virtio''/></disk></devices></domain>"], "expected": {"name": "big", "memory_kib": 1000001, "current_kib": 1000001, "vcpus": 2, "current_vcpus": 2, "disks": ["vda", "vdb", "vdc", "vdd", "vde", "vdf", "vdg", "vdh", "vdi", "vdj", "vdk", "vdl", "vdm", "vdn", "vdo", "vdp", "vdq", "vdr", "vds", "vdt", "vdu", "vdv", "vdw", "vdx", "vdy", "vdz"], "next_disk": "vdaa"}}, {"args": ["<domain type=''kvm''><name>kb</name><memory unit=''KB''>3</memory><currentMemory unit=''bytes''>1025</currentMemory><vcpu current=''1''>3</vcpu></domain>"], "expected": {"name": "kb", "memory_kib": 3, "current_kib": 2, "vcpus": 3, "current_vcpus": 1, "disks": [], "next_disk": "vda"}}]}');
